use clap::{Parser, Subcommand};
use colored::Colorize;
use futures_util::StreamExt;
use reqwest::Client;
use rustyline::error::ReadlineError;
use rustyline::DefaultEditor;
use serde::{Deserialize, Serialize};
use std::fs;
use std::io::{self, Write};
use termimad::print_text;
use walkdir::WalkDir;

const OLLAMA_URL: &str = "http://localhost:11434";

#[derive(Parser)]
#[command(name = "zy")]
#[command(about = "A super powerful local LLM CLI Agent", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    /// The model to use by default
    #[arg(short, long, default_value = "llama2")]
    model: String,

    /// Global system prompt to define the model's persona
    #[arg(short, long)]
    system: Option<String>,
}

#[derive(Subcommand)]
enum Commands {
    /// List available local models
    List,
    /// Start a chat session or send a single prompt
    Chat {
        /// The prompt to send. If empty, starts an interactive session.
        prompt:

Vec<String>,

        /// Model to use for this chat session
        #[arg(short, long)]
        model: Option<String>,

        /// Attach the contents of these files as context
        #[arg(short, long)]
        file: Vec<String>,

        /// System prompt specific to this chat
        #[arg(short, long)]
        system: Option<String>,

        /// Enable agent mode (allows the model to execute tools like bash and file writing)
        #[arg(short, long)]
        agent: bool,

        /// Persistent session name (saves and loads chat history)
        #[arg(long)]
        session: Option<String>,

        /// Enable Retrieval-Augmented Generation (RAG) using local indexed codebase
        #[arg(short, long)]
        rag: bool,

        /// Print output nicely formatted as Markdown (disables streaming)
        #[arg(short='m', long)]
        markdown: bool,
    },
    /// Index a directory for RAG
    Index {
        /// The directory to index
        #[arg(d

efault_value = ".")]
        path: String,
    }
}

#[derive(Serialize, Deserialize, Clone)]
struct ToolCallFunction {
    name: String,
    arguments: serde_json::Value,
}

#[derive(Serialize, Deserialize, Clone)]
struct ToolCall {
    function: ToolCallFunction,
}

#[derive(Serialize, Deserialize, Clone)]
struct Message {
    role: String,
    content: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    tool_calls: Option<Vec<ToolCall>>,
}

#[derive(Serialize)]
struct ChatRequest {
    model: String,
    messages: Vec<Message>,
    stream: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    tools: Option<serde_json::Value>,
}

#[derive(Deserialize)]
struct ChatResponse {
    message: Option<Message>,
    #[allow(dead_code)]
    pub done: bool,
    error: Option<String>,
}

#[derive(Deserialize)]
struct ModelList {
    models: Vec<ModelInfo>,
}

#[derive(Deserialize)]
struct ModelInfo {
    name: String,
}

// RAG structs
#[derive(Serialize, Deserialize)]
str

uct EmbedRequest {
    model: String,
    prompt: String,
}

#[derive(Deserialize)]
struct EmbedResponse {
    embedding: Vec<f32>,
}

#[derive(Serialize, Deserialize)]
struct RagChunk {
    file: String,
    text: String,
    vector: Vec<f32>,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();
    let client = Client::new();

    match &cli.command {
        Some(Commands::List) => {
            list_models(&client).await?;
        }
        Some(Commands::Index { path }) => {
            build_rag_index(&client, path).await?;
        }
        Some(Commands::Chat { prompt, model, file, system, agent, session, rag, markdown }) => {
            let model_name = model.as_deref().unwrap_or(&cli.model);
            let sys_prompt = system.as_deref().or(cli.system.as_deref());

            if prompt.is_empty() {
                interactive_chat(&client, model_name, sys_prompt, file, *agent, session.as_deref(), *rag, *markdo

wn).await?;
            } else {
                let text = prompt.join(" ");
                single_prompt(&client, model_name, sys_prompt, file, &text, *agent, session.as_deref(), *rag, *markdown).await?;
            }
        }
        None => {
            interactive_chat(&client, &cli.model, cli.system.as_deref(), &[], false, None, false, false).await?;
        }
    }

    Ok(())
}

async fn list_models(client: &Client) -> Result<(), Box<dyn std::error::Error>> {
    let res = client.get(format!("{}/api/tags", OLLAMA_URL)).send().await?;

    if res.status().is_success() {
        let list: ModelList = res.json().await?;
        println!("{}", "Available Models:".bold().green());
        for m in list.models {
            println!("  {} {}", "-".cyan(), m.name.yellow());
        }
    } else {
        println!("{}", "Failed to fetch models. Is Ollama running?".red());
    }
    Ok(())
}

fn load_session(session: Option<&str>) -> Vec<Message> {
    if let Some(name) = session

 {
        let file_path = format!(".zy_session_{}.json", name);
        if let Ok(data) = fs::read_to_string(&file_path) {
            if let Ok(msgs) = serde_json::from_str(&data) {
                println!("{} {}", "Loaded session:".blue(), name.bold());
                return msgs;
            }
        }
    }
    Vec::new()
}

fn save_session(session: Option<&str>, messages: &[Message]) {
    if let Some(name) = session {
        let file_path = format!(".zy_session_{}.json", name);
        if let Ok(data) = serde_json::to_string_pretty(messages) {
            let _ = fs::write(file_path, data);
        }
    }
}

async fn embed_text(client: &Client, text: &str) -> Result<Vec<f32>, Box<dyn std::error::Error>> {
    let req = EmbedRequest {
        model: "nomic-embed-text".to_string(),
        prompt: text.to_string(),
    };
    let res = client.post(format!("{}/api/embeddings", OLLAMA_URL)).json(&req).send().await?;
    if res.status().is_success() {
        let parsed: EmbedRe

sponse = res.json().await?;
        Ok(parsed.embedding)
    } else {
        Err("Failed to get embedding".into())
    }
}

fn dot_product(a: &[f32], b: &[f32]) -> f32 {
    a.iter().zip(b.iter()).map(|(x, y)| x * y).sum()
}

async fn apply_rag(client: &Client, prompt: &str, messages: &mut Vec<Message>) -> Result<(), Box<dyn std::error::Error>> {
    let index_file = ".zy_rag_index.json";
    if let Ok(data) = fs::read_to_string(index_file) {
        if let Ok(chunks) = serde_json::from_str::<Vec<RagChunk>>(&data) {
            if chunks.is_empty() { return Ok(()); }

            print!("{} ", "🔍 Searching local codebase (RAG)...".magenta());
            io::stdout().flush()?;

            let query_vec = embed_text(client, prompt).await?;
            let mut scored: Vec<(f32, &RagChunk)> = chunks.iter()
                .map(|c| (dot_product(&query_vec, &c.vector), c))
                .collect();

            scored.sort_by(|a, b| b.0.partial_cm

p(&a.0).unwrap());

            let mut context_text = String::from("Relevant codebase context via RAG:\n");
            for (score, chunk) in scored.iter().take(3) {
                if *score > 10.0 { // arbitrary low threshold for nomic
                    context_text.push_str(&format!("--- FILE: {} ---\n{}\n\n", chunk.file, chunk.text));
                }
            }

            messages.push(Message {
                role: "system".to_string(),
                content: context_text,
                tool_calls: None,
            });
            println!("{}", "Done".green());
        }
    } else {
        println!("{}", "RAG enabled but index not found. Run 'zy index .' first.".red());
    }
    Ok(())
}

async fn build_rag_index(client: &Client, path: &str) -> Result<(), Box<dyn std::error::Error>> {
    println!("{} {}", "Indexing directory:".bold(), path.cyan());
    let mut chunks = Vec::new();

    for entry in WalkDir::new(path).into_iter().fil

ter_map(|e| e.ok()) {
        let path_str = entry.path().to_string_lossy().to_string();
        if path_str.contains("/target/") || path_str.contains("/.git/") || path_str.contains("node_modules") {
            continue;
        }
        if entry.file_type().is_file() {
            if let Ok(content) = fs::read_to_string(entry.path()) {
                // simple naive chunking
                let chunk_size = 1000;
                let chars: Vec<char> = content.chars().collect();
                for (i, chnk) in chars.chunks(chunk_size).enumerate() {
                    let text: String = chnk.iter().collect();
                    if text.trim().is_empty() { continue; }

                    print!("Embedding {} chunk {} ... ", path_str.blue(), i);
                    io::stdout().flush()?;

                    if let Ok(vector) = embed_text(client, &text).await {
                        chunks.push(RagChunk {
                            file: p

ath_str.clone(),
                            text,
                            vector,
                        });
                        println!("{}", "OK".green());
                    } else {
                        println!("{}", "Failed".red());
                    }
                }
            }
        }
    }

    let json_data = serde_json::to_string(&chunks)?;
    fs::write(".zy_rag_index.json", json_data)?;
    println!("{} {} chunks", "Indexed & saved".green().bold(), chunks.len());
    Ok(())
}

fn build_initial_messages(system: Option<&str>, files: &[String]) -> Result<Vec<Message>, Box<dyn std::error::Error>> {
    let mut messages = Vec::new();

    if let Some(sys) = system {
        messages.push(Message {
            role: "system".to_string(),
            content: sys.to_string(),
            tool_calls: None,
        });
    }

    for path in files {
        let content = fs::read_to_string(path)?;
        let file_context = format!("File context for '{}'

:\n```\n{}\n```", path, content);
        messages.push(Message {
            role: "system".to_string(),
            content: file_context,
            tool_calls: None,
        });
        println!("{} {}", "Attached file:".blue(), path.bold());
    }

    Ok(messages)
}

async fn single_prompt(
    client: &Client, 
    model: &str, 
    system: Option<&str>, 
    files: &[String], 
    prompt: &str,
    agent: bool,
    session: Option<&str>,
    rag: bool,
    markdown: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut messages = load_session(session);
    let mut init_msgs = build_initial_messages(system, files)?;
    messages.append(&mut init_msgs);

    if rag {
        apply_rag(client, prompt, &mut messages).await?;
    }

    messages.push(Message {
        role: "user".to_string(),
        content: prompt.to_string(),
        tool_calls: None,
    });

    if agent {
        agent_loop(client, model, &mut messages, markdown).await?;
    } else {

      if markdown {
            let res = fetch_full_response(client, model, &messages).await?;
            print_text(&res);
            messages.push(Message { role: "assistant".to_string(), content: res, tool_calls: None });
        } else {
            let res = stream_response(client, model, &messages).await?;
            println!();
            messages.push(Message { role: "assistant".to_string(), content: res, tool_calls: None });
        }
    }

    save_session(session, &messages);
    Ok(())
}

async fn interactive_chat(
    client: &Client, 
    model: &str, 
    system: Option<&str>, 
    files: &[String],
    agent: bool,
    session: Option<&str>,
    rag: bool,
    markdown: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    println!("{} {}", "Starting interactive session with model:".bold(), model.cyan());
    if agent {
        println!("{}", "⚡ Agent Mode Enabled (Can run bash commands and write files)".yellow().bold());
    }
    if rag {
        println!(

"{}", "🔍 RAG Enabled (Will search local codebase before answering)".magenta().bold());
    }
    println!("Type 'exit' or 'quit' to end the session.\n");

    let mut rl = DefaultEditor::new()?;
    let mut messages = load_session(session);
    let mut init_msgs = build_initial_messages(system, files)?;
    messages.append(&mut init_msgs);

    loop {
        let readline = rl.readline("zy> ");
        match readline {
            Ok(line) => {
                let input = line.trim();
                if input.is_empty() { continue; }
                if input.eq_ignore_ascii_case("exit") || input.eq_ignore_ascii_case("quit") { break; }

                rl.add_history_entry(input)?;

                if rag {
                    apply_rag(client, input, &mut messages).await?;
                }

                messages.push(Message {
                    role: "user".to_string(),
                    content: input.to_string(),
                    tool_calls:

None,
               });

               if agent {
                   agent_loop(client, model, &mut messages, markdown).await?;
               } else {
                   if markdown {
                       let response_text = fetch_full_response(client, model, &messages).await?;
                       print_text(&response_text);
                       messages.push(Message {
                           role: "assistant".to_string(),
                           content: response_text,
                           tool_calls: None,
                       });
                   } else {
                       let response_text = stream_response(client, model, &messages).await?;
                       println!();
                       messages.push(Message {
                           role: "assistant".to_string(),
                           content: response_text,
                           tool_calls: None,
                       });
                   }

      }
                save_session(session, &messages);
            }
            Err(ReadlineError::Interrupted) | Err(ReadlineError::Eof) => { break; }
            Err(err) => { println!("Error: {:?}", err); break; }
        }
    }
    Ok(())
}

async fn stream_response(client: &Client, model: &str, messages: &[Message]) -> Result<String, Box<dyn std::error::Error>> {
    let req_body = ChatRequest {
        model: model.to_string(),
        messages: messages.to_vec(),
        stream: true,
        tools: None,
    };

    let mut res = client.post(format!("{}/api/chat", OLLAMA_URL)).json(&req_body).send().await?;

    if !res.status().is_success() {
        println!("{}", format!("Error: Failed to get response from Ollama. Ensure model '{}' is installed.", model).red());
        return Ok(String::new());
    }

    let mut full_response = String::new();
    let mut stream = res.bytes_stream();

    print!("{}", "zy: ".green().bold());
    io::stdout().flush()?;

    while le

t Some(chunk_result) = stream.next().await {
        let chunk = chunk_result?;
        let chunk_str = String::from_utf8_lossy(&chunk);

        for line in chunk_str.lines() {
            if line.is_empty() { continue; }
            if let Ok(parsed) = serde_json::from_str::<ChatResponse>(line) {
                if let Some(msg) = parsed.message {
                    print!("{}", msg.content);
                    io::stdout().flush()?;
                    full_response.push_str(&msg.content);
                }
                if let Some(err) = parsed.error {
                    println!("\nOllama error: {}", err);
                }
            }
        }
    }

    Ok(full_response)
}

async fn fetch_full_response(client: &Client, model: &str, messages: &[Message]) -> Result<String, Box<dyn std::error::Error>> {
    let req_body = ChatRequest {
        model: model.to_string(),
        messages: messages.to_vec(),
        stream: false,
        tools: None,
    };

print!("{} ", "zy is thinking...".green().bold());
    io::stdout().flush()?;

    let res = client.post(format!("{}/api/chat", OLLAMA_URL)).json(&req_body).send().await?;
    println!("\r                      \r"); // clear thinking line

    if !res.status().is_success() {
        return Ok(format!("Error: Failed to get response. Is model '{}' installed?", model));
    }

    let parsed: ChatResponse = res.json().await?;
    if let Some(msg) = parsed.message {
        Ok(msg.content)
    } else {
        Ok(String::new())
    }
}

fn get_tools() -> serde_json::Value {
    serde_json::json!([
        {
            "type": "function",
            "function": {
                "name": "run_bash",
                "description": "Execute a bash command in the current directory.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "command": { "type": "string", "description": "The command to run" }

               },
                    "required": ["command"]
                }
            }
        },
        {
            "type": "function",
            "function": {
                "name": "write_file",
                "description": "Write content to a file.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "path": { "type": "string", "description": "Path to the file" },
                        "content": { "type": "string", "description": "Content to write" }
                    },
                    "required": ["path", "content"]
                }
            }
        }
    ])
}

async fn agent_loop(client: &Client, model: &str, messages: &mut Vec<Message>, markdown: bool) -> Result<(), Box<dyn std::error::Error>> {
    loop {
        let req_body = ChatRequest {
            model: model.to_string(),
            messages: messages.to_vec(),
            stream: false,
            tools: Some(

get_tools()),
        };

        let res = client.post(format!("{}/api/chat", OLLAMA_URL)).json(&req_body).send().await?;

        if !res.status().is_success() {
            println!("{}", "Error: Failed to get response from Ollama.".red());
            break;
        }

        let parsed: ChatResponse = res.json().await?;
        if let Some(msg) = parsed.message {
            if let Some(calls) = &msg.tool_calls {
                messages.push(msg.clone());

                for call in calls {
                    let fn_name = &call.function.name;
                    let args = &call.function.arguments;
                    let mut tool_result = String::new();

                    print!("{} {}({}) ... ", "⚙️  Tool Call:".magenta().bold(), fn_name.cyan(), args.to_string().yellow());
                    io::stdout().flush()?;

                    if fn_name == "run_bash" {
                        if let Some(cmd) = args.get("command").and_then(|v| v.as_str()) {

let output = std::process::Command::new("sh").arg("-c").arg(cmd).output();
                     match output {
                         Ok(out) => {
                             let stdout = String::from_utf8_lossy(&out.stdout).to_string();
                             let stderr = String::from_utf8_lossy(&out.stderr).to_string();
                             tool_result = format!("STDOUT:\n{}\nSTDERR:\n{}", stdout, stderr);
                             println!("{}", "Done".green());
                         }
                         Err(e) => {
                             tool_result = format!("Failed to execute: {}", e);
                             println!("{}", "Failed".red());
                         }
                     }
                 } else {
                     tool_result = "Error: Missing command parameter".to_string();
                     println!("{}"

, "Failed".red());
                        }
                    } else if fn_name == "write_file" {
                        if let (Some(path), Some(content)) = (args.get("path").and_then(|v| v.as_str()), args.get("content").and_then(|v| v.as_str())) {
                            match fs::write(path, content) {
                                Ok(_) => {
                                    tool_result = format!("Successfully wrote to {}", path);
                                    println!("{}", "Done".green());
                                }
                                Err(e) => {
                                    tool_result = format!("Failed to write file: {}", e);
                                    println!("{}", "Failed".red());
                                }
                            }
                        } else {
                            tool_result = "Error: Missing path or content parameter".to_string();
                            println!("{}", "Failed

".red());
                        }
                    } else {
                        tool_result = format!("Unknown function: {}", fn_name);
                        println!("{}", "Unknown".red());
                    }

                    messages.push(Message {
                        role: "tool".to_string(),
                        content: tool_result,
                        tool_calls: None,
                    });
                }
            } else {
                if markdown {
                    print_text(&msg.content);
                } else {
                    println!("{} {}", "zy:".green().bold(), msg.content);
                }
                messages.push(msg.clone());
                break;
            }
        } else {
            break;
        }
    }
    Ok(())
}
